import test from 'node:test';
import assert from 'node:assert/strict';
import { normalize } from '../src/normalize.js';

const stringCases = [
  ['trims spaces and lowercases letters', '  HeLLo  ', 'hello'],
  ['trims tabs and newlines', '\tMiXeD\n', 'mixed'],
  ['preserves internal whitespace', ' A  B\tC\nD ', 'a  b\tc\nd'],
  ['accepts an empty string', '', ''],
  ['returns empty for all-whitespace input', ' \t\r\n ', ''],
  ['leaves an already normalized string unchanged', 'hello  world', 'hello  world'],
];

for (const [description, input, expected] of stringCases) {
  test(description, () => {
    assert.equal(normalize(input), expected);
  });
}

const nonStringCases = [
  ['undefined', undefined],
  ['null', null],
  ['false', false],
  ['true', true],
  ['zero', 0],
  ['positive number', 42],
  ['negative fraction', -1.5],
  ['NaN', NaN],
  ['infinity', Infinity],
  ['bigint', 1n],
  ['symbol', Symbol('text')],
  ['empty array', []],
  ['string array', ['hello']],
  ['plain object', {}],
  ['object with string conversion', { toString: () => 'hello' }],
  ['function', () => 'hello'],
  ['boxed string', new String('hello')],
];

for (const [description, input] of nonStringCases) {
  test(`rejects ${description} with TypeError`, () => {
    assert.throws(() => normalize(input), TypeError);
  });
}

